[workspace]
members = [
  "apps",
  "buffer-pool",
  "datagram-socket",
  "h3i",
  "netlog",
  "octets",
  "qlog",
  "qlog-dancer",
  "quiche",
  "task-killswitch",
  "tokio-quiche",
]
exclude = ["fuzz", "tools/http3_test"]
resolver = "2"

[workspace.package]
edition = "2021"
repository = "https://github.com/cloudflare/quiche"
license = "BSD-2-Clause"
readme = "README.md"
keywords = ["quic", "http3"]
categories = ["network-programming"]

[workspace.lints.clippy]
mem_forget = "deny"

[workspace.lints.rust]
unexpected_cfgs = { level = "warn", check-cfg = [
  'cfg(capture_keylogs)',
  'cfg(test_invalid_len_compilation_fail)',
  'cfg(boring_v5)',
] }

[workspace.metadata.release]
pre-release-commit-message = "{{crate_name}}: release {{version}}"
consolidate-commits = false
tag-prefix = "{{crate_name}}-"
tag-name = "{{prefix}}{{version}}"
tag-message = "{{crate_name}} {{version}}"
publish = false

[workspace.dependencies]
anyhow = { version = "1" }
assert_matches = { version = "1" }
# Accept both `boring` 4.x (>= 4.19, the MSRV for the APIs we use)
# and `boring` 5.x. The active version is picked by cargo's resolver
# based on the lockfile / downstream constraints; quiche's `build.rs`
# detects which one was selected and emits `cfg(boring_v5)` for the
# 5.x case so source code can switch on it. 4.x is the assumed
# default. `boring-sys` >= 5.2 exports `DEP_BORINGSSL_VERSION_MAJOR`,
# which `build.rs` uses for detection. See `quiche/src/build.rs` and
# the `boringssl-boring-crate` feature in `quiche/Cargo.toml`.
#
# `boring-sys` uses `links = "boringssl"`, so only one major version
# can ever be in the dep graph at a time.
